import { api } from "./src/backend/api";
import type { CommerceEnv } from "./src/backend/types";
// Generated by the framework build; intentionally imported only by Wrangler.
// @ts-expect-error generated JavaScript entry has no declaration file
import storefront from "./.output/server/index.mjs";

export default {
  async fetch(request: Request, env: CommerceEnv, ctx: ExecutionContext): Promise<Response> {
    const url = new URL(request.url);
    // www.<primary host> is served only to redirect to the primary storefront domain.
    const primary = new URL(env.APP_ORIGIN);
    if (url.hostname === `www.${primary.hostname}`)
      return new Response(null, {
        status: 301,
        headers: {
          Location: `${primary.origin}${url.pathname}${url.search}`,
          "Cache-Control": "public,max-age=3600",
        },
      });
    // Routes and Access are additional controls, not substitutes for an origin boundary.
    if (url.hostname !== primary.hostname || url.port !== primary.port)
      return new Response("Unrecognized application host", {
        status: 421,
        headers: { "Cache-Control": "no-store" },
      });
    if (url.protocol === "http:" && primary.protocol === "https:")
      return new Response(null, {
        status: 308,
        headers: {
          Location: `${primary.origin}${url.pathname}${url.search}`,
          "Cache-Control": "no-store",
        },
      });
    if (url.origin !== primary.origin)
      return new Response("Unrecognized application origin", {
        status: 421,
        headers: { "Cache-Control": "no-store" },
      });
    const path = url.pathname;
    if (path.startsWith("/api/")) return api(request, env);
    if (path.startsWith("/media/")) {
      const key = path.slice(7);
      if (!/^[a-f0-9-]+\.(png|jpg|webp)$/.test(key) || !env.MEDIA)
        return new Response("Not found", { status: 404 });
      const visible = await env.DB.prepare(
        "SELECT id FROM products WHERE status='active' AND EXISTS(SELECT 1 FROM json_each(images) WHERE ? IN (json_extract(value,'$.url'),json_extract(value,'$.thumb'))) UNION ALL SELECT id FROM banners WHERE active=1 AND image_url=? LIMIT 1",
      )
        .bind(path, path)
        .first();
      if (!visible) return new Response("Not found", { status: 404 });
      // Keys are random per upload and never rewritten, so the ETag lets a returning visitor
      // revalidate with a 304 instead of downloading the photograph again.
      const image = await env.MEDIA.get(key, { onlyIf: request.headers });
      if (!image) return new Response("Not found", { status: 404 });
      const headers = {
        ETag: image.httpEtag,
        "X-Content-Type-Options": "nosniff",
        "Cache-Control": "public,max-age=3600",
      };
      if (!("body" in image)) return new Response(null, { status: 304, headers });
      return new Response(image.body, {
        headers: {
          ...headers,
          "Content-Type": image.httpMetadata?.contentType ?? "application/octet-stream",
        },
      });
    }
    const response = await storefront.fetch(request, env, ctx);
    const headers = new Headers(response.headers);
    headers.set("X-Content-Type-Options", "nosniff");
    headers.set("Referrer-Policy", "strict-origin-when-cross-origin");
    headers.set("Permissions-Policy", "camera=(), microphone=(), geolocation=()");
    headers.set(
      "Content-Security-Policy",
      "frame-ancestors 'none'; object-src 'none'; base-uri 'self'; form-action 'self'",
    );
    if (env.APP_ORIGIN.startsWith("https:"))
      headers.set("Strict-Transport-Security", "max-age=31536000");
    if (path === "/admin" || path === "/account" || path === "/checkout")
      headers.set("Cache-Control", "no-store");
    return new Response(response.body, { status: response.status, headers });
  },
} satisfies ExportedHandler<CommerceEnv>;
